// UNIFIED INPUT PARSER - Chat + Evaluation

const input = $input.first().json;

// Identify which trigger supplied the input
const evaluationMode =
  typeof input.chatInput !== 'string';

// Get the appropriate input text
const rawInput = evaluationMode
  ? String(input.product_category || '')
  : input.chatInput;

const normalizedInput = rawInput
  .toLowerCase()
  .replace(/[_-]/g, ' ');

const categories = [
  {
    key: 'area_rug',
    displayName: 'Area Rug',
    patterns: ['area rug', 'area rugs']
  },
  {
    key: 'outdoor_rug',
    displayName: 'Outdoor Rug',
    patterns: ['outdoor rug', 'outdoor rugs', 'patio rug', 'patio rugs']
  },
  {
    key: 'hallway_runner',
    displayName: 'Hallway Runner',
    patterns: ['hallway runner', 'runner rug', 'hall runner', 'runners', 'hallway runners']
  },
  {
    key: 'shag_rug',
    displayName: 'Shag Rug',
    patterns: ['shag rug', 'shag rugs', 'shaggy rug', 'shaggy rugs']
  }
];

let detectedCategory = null;

for (const cat of categories) {
  if (cat.patterns.some(pattern =>
    normalizedInput.includes(pattern)
  )) {
    detectedCategory = cat;
    break;
  }
}

// Focus keyword applies to chat input

const focusMatch = evaluationMode
  ? null
  : rawInput.match(/focus\s*:\s*([^\n]+)/i);

const focus = focusMatch
  ? focusMatch[1].trim()
  : String($('Evaluation Trigger').first().json.TestFocus|| '').trim();

const hasCategory = !!detectedCategory;

return [{
  json: {
    // Preserve existing research parser fields
    category: detectedCategory?.key || null,
    categoryKey: detectedCategory?.key || null,
    categoryDisplayName: detectedCategory?.displayName || null,
    focus,
    hasValidInput: hasCategory,
    errorReason: hasCategory ? null : 'no_category',
    originalInput: rawInput,
    parsedAt: new Date().toISOString(),

    // Evaluation fields
    evaluation_mode: evaluationMode,
    test_id: evaluationMode ? input.test_id : null,
    expected_sections: evaluationMode
      ? input.expected_sections
      : null,
    product_category: evaluationMode
      ? input.product_category
      : detectedCategory?.displayName || null
  }
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    wayfair_products: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWayfair: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    amazonProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalAmazonProducts: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    walmartProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWalmartProducts: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// SCOPE GENERATOR - No AI, just JavaScript
// Generates Section 2: Scope of Research

// Keep product link labels short instead of displaying full SEO titles
function shortProductName(p) {
  const title = String(p.name || p.title || 'View product')
    .replace(/\s+/g, ' ')
    .trim();

  const words = title.split(' ');
  return words.length > 7
    ? words.slice(0, 7).join(' ') + '…'
    : title;
}

const wayfairData = $('Reshape Wayfair Response').first().json;
const amazonData = $('Reshape Amazon Response').first().json;
let walmartData = {};
try { walmartData = $('Reshape Walmart Response').first().json || {}; } catch(e) {}
const inputData = $('InputParser').first().json;

const category = inputData.categoryDisplayName || 'Rugs';
const verifiedStats = $('VerifiedSatsCalculator').first().json.verifiedStats || {};
const amazonProductCount = verifiedStats.amazon?.productCount ?? amazonData.amazonProducts?.length ?? 0;
const wayfairProductCount = verifiedStats.wayfair?.productCount ?? wayfairData.wayfair_products?.length ?? 0;
const walmartProductCount = verifiedStats.walmart?.productCount ?? walmartData.walmartProducts?.length ?? 0;


const scopeHtml = `
<section class="scope-section">
  <h2>Scope of Research</h2>
  <div class="scope-grid">
    <div class="scope-card">
      <h4>Category Analyzed</h4>
      <p class="scope-value">${category}</p>
    </div>
    <div class="scope-card">
      <h4>Competitors Reviewed</h4>
      <ul>
        <li><strong>Amazon</strong> - ${amazonProductCount} products analyzed</li>
        <li><strong>Walmart</strong> - ${walmartProductCount} products analyzed</li>
        <li><strong>Wayfair</strong> - ${wayfairProductCount} products (baseline)</li>
      </ul>
    </div>
    <div class="scope-card">
  <h4>Data Sources & Products Reviewed</h4>

  <details>
    <summary>Amazon (${amazonProductCount} products)</summary>
    <ol>
      ${amazonData.amazonProducts.map(p =>
        `<li><a href="${p.url}" target="_blank" rel="noopener noreferrer">${shortProductName(p)}</a></li>`
      ).join('')}
    </ol>
  </details>

  <details>
    <summary>Walmart (${walmartProductCount} products)</summary>
    <ol>
      ${walmartData.walmartProducts.map(p =>
        `<li><a href="${p.url}" target="_blank" rel="noopener noreferrer">${shortProductName(p)}</a></li>`
      ).join('')}
    </ol>
  </details>

  <details>
    <summary>Wayfair (${wayfairProductCount} products)</summary>
    <ol>
      ${wayfairData.wayfair_products.map(p =>
        `<li><a href="${p.url}" target="_blank" rel="noopener noreferrer">${shortProductName(p)}</a></li>`
      ).join('')}
    </ol>
  </details>
</div>
    <div class="scope-card">
      <h4>Report Generated</h4>
      <p class="scope-value">${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}</p>
    </div>
  </div>
</section>
`;

return [{
  json: {
    section: 'scope',
    html: scopeHtml,
    metadata: {
      category,
      amazonProductCount,
      walmartProductCount,
      wayfairProductCount,
      generatedAt: new Date().toISOString()
    }
  }
}];

