const category = $('InputParser').first().json.categoryDisplayName || 'Rugs';
const scopeHtml = $('ScopeGeneratorNode').first().json.html || '';
const execSummary = $('ExecuteSummaryGenerator').first().json.output || '';
const amazonAnalysis = $('CompetitorAnalysisGenerator').first().json.output || '';
const comparison = $('ComparisonGenerator').first().json.output || '';
const pricingWhitespace = $('Pricing & Whitespace Generator').first().json.output || '';
