const rawOutput = $input.first().json.output;

if (!rawOutput) {
  throw new Error("AI Evaluation output is empty");
}

const cleanedOutput = rawOutput
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

let result;

try {
  result = JSON.parse(cleanedOutput);
} catch (error) {
  const match = error.message.match(/position (\d+)/);
  const position = match ? Number(match[1]) : 0;

  const start = Math.max(0, position - 300);
  const end = Math.min(cleanedOutput.length, position + 300);

  throw new Error(
    "Invalid AI Evaluation JSON: " +
    error.message +
    "\n\nProblematic JSON section:\n" +
    cleanedOutput.substring(start, end)
  );
}
// Normalize field names
const normalized = {};

for (const [key, value] of Object.entries(result)) {
  const normalizedKey = key
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, '_');

  normalized[normalizedKey] = value;
}

const dimensions = [
  "factual_accuracy",
  "completeness",
  "data_consistency",
  "relevance",
  "insight_quality",
  "html_quality",
  "source_link_verification"
];

const scores = {};
const summaries = {};
const dimensionIssues = {};

// Extract score, summary and issues from each dimension
for (const key of dimensions) {
  const dimension = normalized[key];

  const score = Number(
    dimension && typeof dimension === "object"
      ? dimension.score
      : dimension
  );

  if (!Number.isInteger(score) || score < 1 || score > 5) {
    throw new Error(
      `Invalid score for ${key}: ${
        dimension && typeof dimension === "object"
          ? JSON.stringify(dimension)
          : dimension
      }`
    );
  }

  scores[key] = score;

  summaries[key] =
    dimension && typeof dimension === "object"
      ? dimension.summary || ""
      : "";

  dimensionIssues[key] =
    dimension && typeof dimension === "object" &&
    Array.isArray(dimension.issues)
      ? dimension.issues
      : [];
}

// Extract missing sections from completeness
const completeness = normalized.completeness || {};

const missingSections =
  typeof completeness === "object" &&
  Array.isArray(completeness.missing_sections)
    ? completeness.missing_sections
    : [];

// Collect all dimension-specific issues
const allFindings = [
  ...Object.entries(dimensionIssues).flatMap(([dimension, issues]) =>
    issues.map(issue => ({
      dimension,
      issue
    }))
  ),
  ...(
    Array.isArray(normalized.data_consistency?.inconsistencies)
      ? normalized.data_consistency.inconsistencies.map(issue => ({
          dimension: "data_consistency",
          issue
        }))
      : []
  ),
  ...(
    Array.isArray(normalized.html_quality?.issues)
      ? normalized.html_quality.issues.map(issue => ({
          dimension: "html_quality",
          issue
        }))
      : []
  )
];

// Include other AI-reported findings
const existingFindings = Array.isArray(normalized.findings)
  ? normalized.findings
  : [];

const keyIssues = Array.isArray(normalized.key_issues)
  ? normalized.key_issues
  : [];

const overallScore =
  dimensions.reduce((sum, key) => sum + scores[key], 0) /
  dimensions.length;

const uniqueFindings = [
  ...new Set([
    ...allFindings.map(item => JSON.stringify(item)),
    ...existingFindings.map(item => JSON.stringify(item)),
    ...keyIssues.map(item => JSON.stringify(item))
  ])
].map(item => JSON.parse(item));

return {
  json: {
    ...normalized,
    ...scores,

    dimension_summaries: summaries,
    dimension_issues: dimensionIssues,

    findings: uniqueFindings,
    key_issues: keyIssues,
    missing_sections: missingSections,

    unsupported_claims: [],
    incorrect_claims: [],

    unsupported_claim_count: 0,
    incorrect_claim_count: 0,
    missing_section_count: missingSections.length,

    total_findings_count: uniqueFindings.length,
    total_report_issues: uniqueFindings.length,

    overall_score: Number(overallScore.toFixed(2)),
    overall_percentage: Number(
      (overallScore / 5 * 100).toFixed(2)
    ),

    evaluation_status: "Completed",
    evaluation_date: new Date().toISOString()
  }
};

const data = $json;

// 1. Evaluation dimensions (all seven)
const dimensions = [
  "factual_accuracy",
  "completeness",
  "data_consistency",
  "relevance",
  "insight_quality",
  "html_quality",
  "source_link_verification"
];

// 2. Validate all seven scores
const scores = dimensions.map(key => {
  const score = Number(data[key]);

  if (!Number.isInteger(score) || score < 1 || score > 5) {
    throw new Error(
      `Invalid evaluation score for ${key}: ${data[key]}`
    );
  }

  return score;
});

// 3. Calculate overall score and percentage
const averageScore =
  scores.reduce((sum, score) => sum + score, 0) /
  dimensions.length;

const overallScore = Number(averageScore.toFixed(2));

const overallPercentage = Number(
  ((averageScore / 5) * 100).toFixed(2)
);

// 4. Count missing sections
const missingSections = Array.isArray(data.missing_sections)
  ? data.missing_sections
  : [];

const missingCount = missingSections.length;

// 5. Get report findings
// Prefer populated findings over key_issues, which may be empty.
const findings = Array.isArray(data.findings) && data.findings.length > 0
  ? data.findings
  : Array.isArray(data.key_issues) && data.key_issues.length > 0
    ? data.key_issues
    : Array.isArray(data.errors)
      ? data.errors
      : [];

// 6. Count recommendation issues separately
const recommendationIssues = Array.isArray(data.issues)
  ? data.issues
  : [];

const totalRecommendationIssues = recommendationIssues.length;

// 7. Count report issues
// Findings are the evaluator's report-level findings.
// Missing sections are included separately if not already represented.
const findingTexts = new Set(
  findings.map(item =>
    typeof item === "string"
      ? item.trim().toLowerCase()
      : JSON.stringify(item).trim().toLowerCase()
  )
);

const totalReportIssues = findings.length +
  missingSections.filter(section => {
    const text = String(section).trim().toLowerCase();
    return !findingTexts.has(text);
  }).length;

// 8. Unsupported and incorrect claim counts
// These remain null until the evaluator explicitly classifies claims.
const unsupportedCount = Array.isArray(data.unsupported_claims)
  ? data.unsupported_claims.length
  : null;

const incorrectCount = Array.isArray(data.incorrect_claims)
  ? data.incorrect_claims.length
  : null;

// 9. Calculate individual dimension percentages
const metrics = {};

for (const key of dimensions) {
  metrics[key + "_percentage"] = Number(
    ((Number(data[key]) / 5) * 100).toFixed(2)
  );
}

// 10. Return final metrics
return {
  json: {
    ...data,
    ...metrics,

    overall_score: overallScore,
    overall_percentage: overallPercentage,

    unsupported_claim_count: unsupportedCount,
    incorrect_claim_count: incorrectCount,
    missing_section_count: missingCount,

    total_findings_count: findings.length,
    total_report_issues: totalReportIssues,
    total_recommendation_issues: totalRecommendationIssues,

    report_quality:
      averageScore >= 4.5 ? "Excellent" :
      averageScore >= 3.5 ? "Good" :
      averageScore >= 2.5 ? "Average" :
      averageScore >= 1.5 ? "Poor" :
      "Very Poor"
  }
};

