const wayfairProducts = $('Reshape Wayfair Response').first().json.wayfair_products || [];
const amazonProducts = $('Reshape Amazon Response').first().json.amazonProducts || [];
const walmartProducts = $('Reshape Walmart Response').first().json.walmartProducts || [];

function parseNumber(val) {
  if (val === null || val === undefined) return NaN;
  const cleaned = String(val).replace(/[^0-9.-]/g, '');
  return parseFloat(cleaned);
}

function parseRating(val) {
  if (val === null || val === undefined) return NaN;
  const match = String(val).match(/(\d+(\.\d+)?)/);
  return match ? parseFloat(match[1]) : NaN;
}

function calculateStats(products) {
  const prices = products.map(p => parseNumber(p.price)).filter(n => !isNaN(n) && n > 0);
  const ratings = products.map(p => parseRating(p.rating)).filter(n => !isNaN(n) && n > 0);
  const reviews = products.map(p => parseNumber(p.review_count || p.reviews)).filter(n => !isNaN(n));

  const count = products.length;
  const minPrice = prices.length ? Math.min(...prices) : 0;
  const maxPrice = prices.length ? Math.max(...prices) : 0;
  const avgPrice = prices.length ? +(prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2) : 0;
  const avgRating = ratings.length ? +(ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(2) : 0;
  const totalReviews = reviews.reduce((a, b) => a + b, 0);

  const budgetCount = prices.filter(p => p < 100).length;
  const midCount = prices.filter(p => p >= 100 && p <= 300).length;
  const premiumCount = prices.filter(p => p > 300).length;

  const hasDiscountData = products.some(
    p => (p.list_price && parseNumber(p.list_price) > parseNumber(p.price)) ||
         (p.originalPrice && parseNumber(p.originalPrice) > parseNumber(p.price))
  );

  return {
    productCount: count,
    minPrice: `$${minPrice.toFixed(2)}`,
    maxPrice: `$${maxPrice.toFixed(2)}`,
    priceRange: `$${minPrice.toFixed(2)} - $${maxPrice.toFixed(2)}`,
    avgPrice: `$${avgPrice.toFixed(2)}`,
    avgRating: avgRating,
    totalReviews: totalReviews,
    priceBands: {
      budgetUnder100: budgetCount,
      mid100To300: midCount,
      premiumOver300: premiumCount
    },
    hasDiscountData: hasDiscountData
  };
}

const verifiedStats = {
  wayfair: calculateStats(wayfairProducts),
  amazon: calculateStats(amazonProducts),
  walmart: calculateStats(walmartProducts)
};

return items.map(item => ({
  json: {
    ...item.json,
    verifiedStats
  }
}));
